from enum import StrEnum


class SecretsKeyOrigin(StrEnum):
    """Where the key in use comes from."""

    SETTING = "setting"
    """`AIOS_SECRETS_KEY`: outside the data dir, as it must be."""
    DATA_DIR = "data_dir"
    """`<data>/secrets.key`, generated by an older ai-os: read until the key is moved
    into the setting, never written any more."""
